const attractionCategories = new Set<TripPlaceCategory>(['Attraction', 'Beach / Sandbank', 'Wildlife / Turtles', 'Spice Farm']);

export const ZANZIBAR_TOURIST_ATTRACTIONS: TripPlace[] = ZANZIBAR_TRIP_PLACES.filter((place) =>
  attractionCategories.has(place.category),
);

export function tripPlacesForGroup(groupId: TripPlaceGroupId): TripPlace[] {
  if (groupId === 'all') return ZANZIBAR_TRIP_PLACES;
  const group = TRIP_PLACE_GROUPS.find((item) => item.id === groupId);
  if (!group) return [];
  const categories = new Set<string>(group.categories);
  return ZANZIBAR_TRIP_PLACES.filter((place) => categories.has(place.category));
}

export function findTripPlace(name: string): TripPlace | undefined {
  const needle = name.trim().toLowerCase();
  return ZANZIBAR_TRIP_PLACES.find((place) => place.name.toLowerCase() === needle);
}

export function tripPlaceMapsUrl(place: TripPlace): string {
  return `https://www.google.com/maps/search/?api=1&query=${place.latitude},${place.longitude}`;
}
